from robot.utils.robottime import timestr_to_secs
from ute_common_store import Store
from ute_common_converter.to_number import to_int, to_float
from ute_common_bts.fsm import FsmServices

from ute_fsmaccess.manager import SSHConnectionManager
from ute_fsmaccess.wtsaccess import WtsFsmAccess
from ute_fsmaccess.exception import FileDoNotExist, DictionaryDoNotExist
from ute_fsmaccess.interface.common import FsmCommonInterface


class WtsFsmInterface(FsmCommonInterface):

    def __init__(self):
        super(WtsFsmInterface, self).__init__()
        self.wts_store = Store()
        self.ssh_forwarder = None

    def setup_wts_fsm_access(self, host='192.168.200.1', user='toor4nsn', password='oZPS0POrRieRtu', port=22,
                             timeout=20.0, prompt=' >',
                             remote_host=None, retry_timeout=60.0, fallback_prompt=None, **kwargs):

        """
        Prepare Ssh Connection to WTS Fsm.

        :param string host:             IP address or domain name of WTS Fsm.
                                        If no value is given, the library will scan for available WTS IP address.
        :param string user:             SSH login.
        :param string password:         SSH password.
        :param integer port:            SSH port.
        :param float timeout:           Timeout for SSH execution commands.
        :param string prompt:           WTS Fsm console prompt.
        :param string remote_host:      Ip address or domain of remote host.
        :param float retry_timeout:     Timeout for retrying SSH login.
        :param string fallback_prompt:  Client will attempt to use this if 'prompt' fails. As consequence, timeout duration will double.
                                        The default value of 'None' will not trigger this behavior.

        :note: The same IP is used for both Host and TRS in WTS.
        :note: **prompt** arguments are kept for backwards compatibility but starting from v.2.35.0 they have no effect.
        |

        :Full support for remote host is available via kwargs:
            * **remote_ssh_user** (string)   - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)   - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string) - SSH prompt received after logging in remote host. Default is '$ '.

        :Other arguments available via kwargs:
            * **trs_user** (string)  - Transport username. Default is 'Nemuadmin'.
            * **trs_pass** (string)  - Transport password. Default is 'nemuuser'.

        """

        port = to_int(port)
        timeout = to_float(timeout)
        retry_timeout = to_float(retry_timeout)

        fsm_service_params = {'trs_ip': host, 'trs_user': kwargs.get('trs_user', 'Nemuadmin'),
                              'trs_pass': kwargs.get('trs_pass', 'nemuuser'), 'timeout': timeout}
        remote_host_params = {'remote_host': remote_host, 'remote_ssh_user': kwargs.get('remote_ssh_user', 'ute'),
                              'remote_ssh_pass': kwargs.get('remote_ssh_pass', 'ute'),
                              'remote_ssh_prompt': kwargs.get('remote_ssh_prompt', '$ ')}
        fsm_service_params.update(remote_host_params)
        manager = SSHConnectionManager(host, user, password, port, timeout, prompt, remote_host, retry_timeout,
                                       fallback_prompt, **kwargs)
        self.wts_store.add(WtsFsmAccess(manager, FsmServices(**fsm_service_params)),
                           alias=kwargs.get('alias'))

    def teardown_wts_fsm_access(self, **kwargs):
        """Close SSH session and cleanup connection.
        """
        self.wts_store.remove(alias=kwargs.get('alias'))

    def teardown_all_aliases_for_wts_fsmaccess(self):
        """ Calls teardown_wts_fsm_access for each alias stored in wts_store
        """
        for alias_name in self.wts_store.aliases:
            self.teardown_wts_fsm_access(alias=alias_name)

    def get_wts_config_file(self, destination, **kwargs):
        """Copy iphy.xml from iphy to specified place on PC.

        :param string destination:     Destination directory path.

        :return:                        Destination path.
        :rtype:                         string
        """
        source, destination = self.wts_store.get(alias=kwargs.get('alias')).get_wts_fsm_config_file(dst=destination)
        return destination

    def put_wts_config_file(self, source, partition='active', **kwargs):
        """Copy iphy.xml file from PC to IPHY.

        :param string source:          Source file path.
        :param string partition:       Partition type, default: active.

        :return:                        Source path.
        :rtype:                         string
        """
        source, destination = self.wts_store.get(alias=kwargs.get('alias')).put_wts_fsm_config_file(src=source,
                                                                                                    partition=partition)
        return source

    def get_wts_sw_version(self, partition='active', **kwargs):
        """Get WTS software version.

        :param string partition:        Partition type, default: active.

        :return:                        Wts software version.
        :rtype:                         string
        """
        return self.wts_store.get(alias=kwargs.get('alias')).get_fsm_sw_version(partition)

    def get_wts_hw_version(self, **kwargs):
        """Get WTS hardware version.

        :return:    Wts hardware version.
        :rtype:    string
        """
        return self.wts_store.get(alias=kwargs.get('alias')).get_fsm_hw_version()

    def file_should_exist_on_wts(self, file_path, **kwargs):
        """ Fails if given file does not exist.

        :param string file_path:    File path.

        :raise:    Exception if directory does not exist
        """
        if not (self.wts_store.get(alias=kwargs.get('alias')).file_exists(file_path)):
            raise FileDoNotExist('File %s DOES NOT exist' % file_path)

    def get_wts_partition_path(self, partition, **kwargs):
        """Get IPHY partition path.

        :param string partition:        Partition type.

        :return:                        Partition path.
        :rtype:                         String
        """
        return self.wts_store.get(alias=kwargs.get('alias')).get_partition_path(partition)

    def dir_should_exist_on_wts(self, dir_path, **kwargs):
        """ Fails if given directory does not exist on WTS.

        :param string dir_path:    Directory path.

        raise:    Exception if directory does not exist
        """
        if not (self.wts_store.get(alias=kwargs.get('alias')).dir_exists(dir_path)):
            raise DictionaryDoNotExist('Dictionary %s DOES NOT exist' % dir_path)

    def execute_command_on_wts(self, cmd, return_rc=False, **kwargs):
        """ Execute shell command on WTS.

        :param string cmd:           Shell command.
        :param bool   return_rc:     Flag for returning shell command rc. Default: False.

        :return:                     Shell command output. If return_rc is True, also returns shell command rc.
        :rtype:                      string or (string, int)
        """
        return self.wts_store.get(alias=kwargs.get('alias')).execute(cmd, return_rc)

    def start_command_on_wts(self, cmd, **kwargs):
        """ Start shell command on WTS. Unlike to "execute command", "start command" does not
        wait for return code

        :param string cmd:      Shell command to be started.

        """
        self.wts_store.get(alias=kwargs.get('alias')).start_command(cmd)

    def get_wts_file(self, source, destination, **kwargs):
        """Copy a file from source on WTS to destination on the local machine.

        :param string source:         Source file path.
        :param string destination:    Destination directory path.

        :return:                     Destination path.
        :rtype:                      string
        """
        source, destination = self.wts_store.get(alias=kwargs.get('alias')).get_fsm_file(src=source, dst=destination)
        return destination

    def get_wts_directory(self, source, tar_output, **kwargs):
        """Copy a directory from source on IPHY to destination on the local machine

        :param source:          Source file directory
        :param tar_output:      Destination output tarfile

        :return tar_output:     Destination output tarfile
        :rtype: string
        :raises: ValueError for invalid filename extension

        :note: These examples will produce the following results for tar_output:
            * filename.tar.bz2 (already has '.tar.bz2' extension)
            * some_filename (will append '.tar.bz2' extension)
            * some_filename.zip (will raise ValueError)
        """
        return self.wts_store.get(alias=kwargs.get('alias')).get_fsm_directory(src=source, tar_output=tar_output)

    def put_wts_file(self, source, destination, partition='active', **kwargs):
        """Copy a file from source on the local machine to destination on WTS.

        :param string source:         Source file path.
        :param string destination:    Destination file path.

        :return:                     Source file path.
        :rtype:                      string
        """
        source, destination = self.wts_store.get(alias=kwargs.get('alias')).put_fsm_file(src=source, dst=destination,
                                                                                         partition=partition)
        return source

    def set_writeable_wts_passive_partition(self, **kwargs):
        """Set read-write permission mode for WTS passive partition."""
        self.wts_store.get(alias=kwargs.get('alias')).set_writeable_wts_passive_partition()

    def enable_wts_ssh(self, timeout='5min', **kwargs):
        """*DEPRECATED*
        Enable SSH services on WTS FSM.

        :param String timeout:      Timeout in enabling SSH. Default is 5min."""
        timeout = timestr_to_secs(timeout)
        return self.wts_store.get(alias=kwargs.get('alias')).enable_ssh(timeout=timeout)
